// Hindi translations of the symptom check-ins in ../symptoms/cycle.ts,
// ../symptoms/intimate.ts and ../symptoms/stages.ts, keyed by flow id, then
// question, option and outcome id. readMore holds translated labels in the
// same order as the English links. Never a diagnosis, never a medicine: every
// red-flag warning, see-a-doctor line, 112 and Tele MANAS 14416 must match the
// English source.

export type SymptomFlowHi = {
  title: string;
  short: string;
  /** Devanagari phrases that should start this check-in when typed. */
  triggers: string[];
  /** Hindi for the flow's notFor line, shown when the profile doesn't fit. */
  notFor?: string;
  questions: Record<string, { text: string; options: Record<string, string> }>;
  outcomes: Record<
    string,
    {
      title: string;
      summary: string;
      oftenLinkedTo: string[];
      whatHelps: string[];
      seeDoctor: string;
      readMore?: string[];
    }
  >;
};

